      const rows=recycle.map(r=>'<p>'+e(({ticket:'Zgłoszenie',blueprint:'Szablon projektu',draft:'Draft projektu'})[r.kind]||r.kind)+' '+e(r.name||r.resource_id)+' · dostępne do '+date(r.expires_at)+' '+button('restore-trash','Odtwórz','data-id="'+r.id+'"')+(r.kind!=='ticket'?button('purge-config','Usuń na stałe','data-id="'+r.id+'"'):'')+'</p>').join('')||'<p>Kosz jest pusty.</p>';
