    $('[data-p22-preferences]', main)?.addEventListener('submit', async ev => { ev.preventDefault(); try { const f = Object.fromEntries(new FormData(ev.target)); await call('notification-preferences', { version: state.preferences.version, config: { ...f, events: new FormData(ev.target).getAll('events'), digest: ev.target.elements.digest.checked } }); notify('Zapisano preferencje.'); await route(); } catch (err) { notify(err.message, true); } }, { signal });
